select id, name from public.clinics where name in ('عيادة فاطمة سالم الجاموس','عيادة حازم محمد الشيخ'); select a.clinic_id, c.name, a.start_time from public.appointments a join public.clinics c on c.id=a.clinic_id where a.appointment_date=current_date and a.status not in ('cancelled','no_show') and a.clinic_id in (select id from public.clinics where name in ('عيادة فاطمة سالم الجاموس','عيادة حازم محمد الشيخ')) order by a.start_time;